SELECT name,posting_date,company,supplier,total,discount_amount,net_total,tax_amount,grand_total,outstanding_amount,update_stock,docstatus FROM "tabPurchase Invoice" WHERE (%(company)s='' OR company=%(company)s) AND (%(supplier)s='' OR supplier=%(supplier)s) AND (%(from_date)s='' OR posting_date>=%(from_date)s) AND (%(to_date)s='' OR posting_date<=%(to_date)s) ORDER BY posting_date,name
